1	"use server";
2	
3	import { createClient } from "@/lib/supabase/server";
4	import { signItemImages, displayPath } from "@/lib/storage/signed";
5	import { fetchForecast } from "@/lib/weather/open-meteo";
6	import { laterAdvice } from "@/lib/weather/advice";
7	import { occasionBand, applyFormalityOverride } from "@/lib/generator/rules";
8	import { buildCandidates, type CandidateItem } from "@/lib/generator/candidates";
9	import { rankTopN } from "@/lib/generator/rank";
10	import { rerank } from "@/lib/generator/rerank";
11	import { layoutForLook, staggerOrder } from "@/lib/generator/layout";
12	import {
13	  resolveLocation,
14	  roundCoord,
15	  LocationInputSchema,
16	  type LocationSource,
17	} from "@/lib/weather/location";
18	import type {
19	  GenerateResult,
20	  Look,
21	  LookPiece,
22	  UiOccasion,
23	  WeatherPayload,
24	} from "@/lib/generator/types";
25	
26	function currentSeason(d: Date): string {
27	  const m = d.getMonth();
28	  return m < 2 || m === 11 ? "Winter" : m < 5 ? "Spring" : m < 8 ? "Summer" : "Autumn";
29	}
30	
31	export async function generate(input: {
32	  occasion: UiOccasion;
33	  formality: number | null;
34	  mustColors: string[];
35	  city?: { lat: number; lon: number; label: string; source: LocationSource };
36	}): Promise<GenerateResult> {
37	  try {
38	    const supabase = await createClient();
39	    const {
40	      data: { user },
41	    } = await supabase.auth.getUser();
42	    if (!user) return { status: "error", message: "Not signed in" };
43	
44	    const { data: profile } = await supabase
45	      .from("profiles")
46	      .select("archetype, location_lat, location_lon, location_label, location_source")
47	      .eq("id", user.id)
48	      .single();
49	    const { data: itemsRaw } = await supabase
50	      .from("items")
51	      .select("*")
52	      .eq("user_id", user.id)
53	      .eq("archived", false);
54	    const items = itemsRaw ?? [];
55	    const byId = new Map(items.map((i) => [i.id, i]));
56	
57	    const loc = resolveLocation({ input: input.city, profile });
58	
59	    const now = new Date();
60	    const f = await fetchForecast(loc.lat, loc.lon);
61	    const advice = laterAdvice(f.hourly);
62	    const weather: WeatherPayload = {
63	      tempC: f.tempC,
64	      feelsLikeC: f.feelsLikeC,
65	      condition: f.condition,
66	      cityLabel: loc.label,
67	      timezone: f.timezone,
68	      locationOrigin: loc.origin,
69	      laterSentence: advice.sentence,
70	      adviceClause: advice.adviceClause,
71	      laterLabel: "Later",
72	      hourly: f.hourly,
73	    };
74	
75	    const candItems: CandidateItem[] = items.map((i) => ({
76	      id: i.id,
77	      category: i.category,
78	      colors: i.colors ?? [],
79	      formality: i.formality,
80	      seasons: i.seasons ?? [],
81	      material: i.material,
82	    }));
83	    const band = applyFormalityOverride(occasionBand(input.occasion), input.formality);
84	    const combos = buildCandidates(candItems, {
85	      band,
86	      weather: { tempC: f.tempC, rain: f.hourly.some((h) => h.isNow && h.rain) },
87	      season: currentSeason(now),
88	      excludeItemIds: [],
89	      mustColors: input.mustColors,
90	      maxAccessories: 1,
91	    });
92	    if (combos.length === 0) return { status: "empty", weather };
93	
94	    const aesthetic = profile?.archetype ? [profile.archetype] : [];
95	    const top = rankTopN(combos, { aesthetic, band }, 20);
96	
97	    const { picks } = await rerank({
98	      combos: top.map((t) =>
99	        t.items.map((ci) => {
100	          const it = byId.get(ci.id)!;
101	          return { category: it.category, subcategory: it.subcategory, colors: it.colors ?? [] };
102	        }),
103	      ),
104	      aesthetic,
105	      occasion: input.occasion,
106	      weatherLabel: f.condition,
107	      tempC: f.tempC,
108	    });
109	
110	    const paths = Array.from(
111	      new Set(top.flatMap((t) => t.items.map((ci) => displayPath(byId.get(ci.id)!)))),
112	    );
113	    const signed = await signItemImages(paths);
114	
115	    const looks: Look[] = picks.map((p) => {
116	      const combo = top[p.combo_index]?.items ?? top[0].items;
117	      const dbItems = combo.map((ci) => byId.get(ci.id)!);
118	      const slots = layoutForLook(dbItems.map((d) => ({ category: d.category })));
119	      const pieces: LookPiece[] = dbItems.map((d, idx) => ({
120	        itemId: d.id,
121	        category: d.category,
122	        subcategory: d.subcategory ?? null,
123	        brand: d.brand ?? null,
124	        name: d.name ?? null,
125	        colors: d.colors ?? [],
126	        cutoutUrl: signed.get(displayPath(d)) ?? "",
127	        slot: slots[idx],
128	      }));
129	      return { name: p.name, why: p.why, pieces, anchorIndex: staggerOrder(slots)[0] };
130	    });
131	
132	    return { status: "ok", weather, looks };
133	  } catch (e) {
134	    console.error("[generate] failed:", e);
135	    return { status: "error", message: e instanceof Error ? e.message : "Generation failed" };
136	  }
137	}
138	
139	/**
140	 * The single write path for a user's location. `generate` stays read-only.
141	 * Called by the client after a successful generate for a location the user
142	 * actually supplied (geolocation or city search) — never for the profile or
143	 * default fallback, where there is nothing new to write.
144	 */
145	export async function saveLocation(input: unknown): Promise<void> {
146	  const d = LocationInputSchema.parse(input);
